// inventoryPageURL preserves q / low with the given page.
func inventoryPageURL(f inventory.ListFilter, page int) string {
	if page < 1 {
		page = 1
	}
	v := url.Values{}
	if f.Query != "" {
		v.Set("q", f.Query)
	}
	if f.LowOnly {
		v.Set("low", "1")
	}
	if page > 1 {
		v.Set("page", fmt.Sprint(page))
	}
	qs := v.Encode()
	if qs == "" {
		return "/inventory/search"
	}
	return "/inventory/search?" + qs
}

